@if($orders->count())<div class="table-wrap"><table><thead><tr><th>Order / customer</th><th>Vehicle</th><th>Service</th><th>Status</th><th>Amount / balance</th><th></th></tr></thead><tbody>@foreach($orders as $order)<tr><td><strong><a href="/orders/{{ $order->id }}">{{ $order->number }}</a></strong><small>{{ $order->vehicle->customer->name }}</small></td><td><strong>{{ $order->vehicle->make_model }}</strong><span class="plate">{{ $order->vehicle->plate }}</span></td><td>{{ $order->items->first()?->name }}@if($order->items->count()>1)<small>+ {{ $order->items->count()-1 }} more</small>@endif<small>{{ $order->scheduled_at?->format('M j, g:i A') ?? $order->created_at->format('M j, g:i A') }}</small></td><td><span class="badge {{ $order->status }}"><span class="dot"></span>{{ $order->status }}</span><small>{{ $order->assignee?->name ?? 'Unassigned' }}</small></td><td><strong>{{ $money($order->total_cents) }}</strong><small>{{ $order->balance_cents>0?$money($order->balance_cents).' due':'Paid in full' }}</small></td><td><a class="text-link" href="/orders/{{ $order->id }}">View →</a></td></tr>@endforeach</tbody></table></div>@else<div class="empty"><x-icon name="car"/><strong>A clear lane, a fresh start.</strong><p>No orders to show here yet.</p>@can('operations')<a href="/orders/new" class="button small">Create a wash order</a>@endcan</div>@endif
